CREATE TABLE IF NOT EXISTS users (id INT AUTO_INCREMENT PRIMARY KEY,nama VARCHAR(100) NOT NULL,username VARCHAR(50) NOT NULL UNIQUE,password VARCHAR(255) NOT NULL,role ENUM('admin','user') NOT NULL DEFAULT 'user',aktif TINYINT(1) NOT NULL DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS kategori (id INT AUTO_INCREMENT PRIMARY KEY,nama VARCHAR(100) NOT NULL UNIQUE,keterangan VARCHAR(255) NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS lokasi (id INT AUTO_INCREMENT PRIMARY KEY,gedung VARCHAR(100) NOT NULL,ruang VARCHAR(100) NULL,rak VARCHAR(100) NULL,keterangan VARCHAR(255) NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS barang (id INT AUTO_INCREMENT PRIMARY KEY,kode VARCHAR(50) NOT NULL UNIQUE,nama VARCHAR(150) NOT NULL,kategori_id INT NULL,stok INT NOT NULL DEFAULT 0,satuan VARCHAR(30) NOT NULL DEFAULT 'Unit',lokasi_id INT NULL,kondisi ENUM('Baik','Rusak Ringan','Rusak Berat') NOT NULL DEFAULT 'Baik',status ENUM('Tersedia','Sedang Digunakan','Dipinjam','Dalam Perbaikan') NOT NULL DEFAULT 'Tersedia',tanggal_masuk DATE NULL,deskripsi TEXT NULL,aktif TINYINT(1) DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,CONSTRAINT fk_barang_kategori FOREIGN KEY(kategori_id) REFERENCES kategori(id) ON DELETE SET NULL,CONSTRAINT fk_barang_lokasi FOREIGN KEY(lokasi_id) REFERENCES lokasi(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS barang_unit (id INT AUTO_INCREMENT PRIMARY KEY,barang_id INT NOT NULL,kode_unit VARCHAR(80) NOT NULL UNIQUE,nama_unit VARCHAR(150) NULL,lokasi_id INT NULL,spesifikasi TEXT NULL,kondisi ENUM('Baik','Rusak Ringan','Rusak Berat') NOT NULL DEFAULT 'Baik',catatan TEXT NULL,status ENUM('tersedia','keluar','rusak') NOT NULL DEFAULT 'tersedia',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_unit_barang FOREIGN KEY(barang_id) REFERENCES barang(id) ON DELETE CASCADE,CONSTRAINT fk_unit_lokasi FOREIGN KEY(lokasi_id) REFERENCES lokasi(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS transaksi (id INT AUTO_INCREMENT PRIMARY KEY,barang_id INT NOT NULL,jenis ENUM('masuk','keluar') NOT NULL,jumlah INT NOT NULL,tanggal DATE NOT NULL,keterangan TEXT NULL,user_id INT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_trans_barang FOREIGN KEY(barang_id) REFERENCES barang(id),CONSTRAINT fk_trans_user FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB;
